import math

def solve(N, K):
    MOD = 10**9 + 7
    result = [0] * (K + 1)

    def choose(n, k):
        if k > n:
            return 0
        return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

    for i in range(1, K + 1):
        result[i] = choose(N - 1, i - 1)
        result[i] %= MOD

    return result[1:]

