def count_arrangements(N, K):
    MOD = 10**9 + 7
    result = [0] * (K + 1)

    # Calculate combinations
    comb_cache = [[0] * (K + 1) for _ in range(N + 1)]
    for n in range(N + 1):
        for k in range(min(n, K) + 1):
            if k == 0 or k == n:
                comb_cache[n][k] = 1
            else:
                comb_cache[n][k] = (comb_cache[n - 1][k - 1] + comb_cache[n - 1][k]) % MOD

    # Calculate the number of valid arrangements for each i
    for i in range(1, K + 1):
        for j in range(i, N + 1):
            result[i] = (result[i] + comb(j - 1, i - 1) * comb(N - j, K - i)) % MOD

    return result[1:]

