import math
MOD = 10**9 + 7

def count_arrangements(N, K):
    def nCr(n, r):
        return math.comb(n, r)

    def count_ways(k):
        if k == K:
            return nCr(N-1, K-1)
        result = 0
        for j in range(K-k):
            result += nCr(j+k, k) * count_ways(k-j-1)
            result %= MOD
        return result

    dp = [0] * (K+1)
    dp[K] = 1
    for i in range(K, 0, -1):
        dp[i-1] = sum(dp[j] for j in range(i, K+1)) % MOD

    result = []
    for i in range(1, K+1):
        ways = 0
        for j in range(K-i+1):
            ways += dp[K-j-1]
            ways %= MOD
        result.append((nCr(N-1, K-1) * ways) % MOD)

    return result

